import React from 'react'

import {Spinner} from '@primer/react'
import {clsx} from 'clsx'

import styles from './RestrictionEditor.module.css'

const CodeMirrorBase = React.lazy(() => import('@github-ui/code-mirror'))

export function RestrictionEditor(props: {
  value?: string
  onChange?(value: string): void
  placeholder?: string
  labelId: string
  fieldStatus?: FormValidationStatus
  disabled?: boolean
}) {
  const {labelId, value, placeholder, fieldStatus, onChange, disabled = false} = props

  // CodeMirror requires an onChange callback provided, but we don't always want that (storybook)
  const onChangeProxy = React.useCallback(
    (newValue: string) => {
      if (!disabled) {
        onChange?.(newValue)
      }
    },
    [onChange, disabled],
  )

  return (
    <React.Suspense fallback={Loading}>
      <Wrapper fieldStatus={fieldStatus}>
        <CodeMirrorBase
          fileName="document.yaml"
          spacing={{
            indentUnit: 2,
            indentWithTabs: false,
            lineWrapping: false,
          }}
          ariaLabelledBy={labelId}
          value={value}
          placeholder={placeholder}
          onChange={onChangeProxy}
          height="400px"
          hideHelpUntilFocus
          isReadOnly={disabled}
        />
      </Wrapper>
    </React.Suspense>
  )
}

const Loading = (
  <div className={styles.loadingContainer}>
    <Spinner size="medium" />
    &nbsp;<span className={styles.loadingText}>Loading...</span>
  </div>
)

// ---

type FormValidationStatus = 'error' | 'success' | 'warning'

const STATUS_CLASSES: Record<FormValidationStatus, string> = {
  error: styles.wrapperError,
  success: styles.wrapperSuccess,
  warning: styles.wrapperWarning,
}

// This tries to mimic `TextInputBaseWrapper` from primer, that is currently not exposed:
// @see: https://github.com/github/primer/issues/2705
function Wrapper({
  fieldStatus,
  children,
}: React.PropsWithChildren<{
  fieldStatus?: FormValidationStatus
}>) {
  return <div className={clsx(styles.wrapper, fieldStatus && STATUS_CLASSES[fieldStatus])}>{children}</div>
}
