import React from 'react'

import {GitHubAvatar} from '@github-ui/github-avatar'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {ownerAvatarPath, ownerPath} from '@github-ui/paths'
import {Heading, Link, RelativeTime} from '@primer/react'
import {clsx} from 'clsx'

import styles from './Ui.module.css'

export function PageHeading(props: {name: React.ReactNode; description?: React.ReactNode; meta?: React.ReactNode}) {
  return (
    <header className="Subhead">
      <div className={styles.pageHeadingContent}>
        <Heading as="h2" className={clsx(styles.pageHeadingTitle, 'Subhead-heading')}>
          {props.name}
        </Heading>
        {props.meta}
      </div>
      {props.description ? <span className="Subhead-description">{props.description}</span> : null}
    </header>
  )
}

export function FeedbackLink() {
  return (
    <Link href="https://gh.io/copilot-content-exclusion-feedback" className={styles.feedbackLink} inline>
      Give feedback
    </Link>
  )
}

const LastEditedByLink = ({children, link}: React.PropsWithChildren<{link: string | undefined}>) => {
  if (link) {
    return (
      <Link className={styles.lastEditedByLink} href={link} data-testid="audit-link">
        {children}
      </Link>
    )
  }
  return <>{children}</>
}

export function LastEditedBy(props: {login: string; time: string; link?: string}) {
  const {login: owner, link} = props
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const hovercardAttrs = getHovercardAttributesForType('user', {login: owner})

  return (
    <div className={styles.lastEditedBy} data-testid="copilot-content-exclusion-last-edited-by">
      <Link
        aria-label={`View ${owner} profile`}
        href={ownerPath({owner})}
        {...hovercardAttrs}
        className={styles.ownerLink}
      >
        <GitHubAvatar src={ownerAvatarPath({owner})} /> <span className={styles.ownerName}>{owner}</span>
      </Link>{' '}
      last edited{' '}
      <LastEditedByLink link={link}>
        <RelativeTime datetime={props.time} tense="past" />
      </LastEditedByLink>
    </div>
  )
}

const STACK_GAP_MAPPING = {
  condensed: 'var(--stack-gap-condensed)',
  normal: 'var(--stack-gap-normal)',
  spacious: 'var(--stack-gap-spacious)',
} as const

export function Stack(
  props: React.PropsWithChildren<
    {space?: number | keyof typeof STACK_GAP_MAPPING} & React.HTMLAttributes<HTMLDivElement>
  >,
) {
  const {children, space, style, ...rest} = props
  const items = simpleFlattenChildren(children)

  if (items.length < 2) return <>{items}</>

  let gap: string | number = space ?? 0
  if (typeof space === 'string') gap = STACK_GAP_MAPPING[space] ?? 0

  return (
    <div className={styles.stack} style={{...style, gap}} {...rest}>
      {
        // eslint-disable-next-line @eslint-react/no-children-map
        React.Children.map(items, (child, index) => (
          // eslint-disable-next-line @eslint-react/no-array-index-key
          <div key={index}>{child}</div>
        ))
      }
    </div>
  )
}

// --

function simpleFlattenChildren(children: React.ReactNode) {
  const kids: React.ReactNode[] = []

  // eslint-disable-next-line github/array-foreach, @eslint-react/no-children-for-each
  React.Children.forEach(children, child => {
    if (React.isValidElement(child)) {
      if (child.type === React.Fragment) {
        const fragmentChild = child as React.ReactElement<React.ComponentProps<typeof React.Fragment>>
        kids.concat(simpleFlattenChildren(fragmentChild.props.children))
        return
      }
      kids.push(child)
    }
  })

  return kids
}
